package org.apache.commons.text;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class WordUtils_ESTest_test17 extends WordUtils_ESTest_scaffolding {

    /**
     * Verifies that {@link WordUtils#isDelimiter(char, char[])} returns {@code false}
     * when the given character is not present in the delimiter array.
     *
     * <p>The delimiter array here holds two null characters (the default value
     * for a freshly allocated {@code new char[2]}), so the letter 'G' matches
     * none of them.</p>
     */
    @Test(timeout = 4000)
    public void isDelimiterReturnsFalseWhenCharNotInDelimiters() throws Throwable {
        char[] delimiters = new char[2];

        boolean result = WordUtils.isDelimiter('G', delimiters);

        assertFalse(result);
    }
}
